 static MirrorEntity create(ServerLevel l,BlockPos p,boolean essence,Direction face){l.setBlockAndUpdate(p.relative(face.getOpposite()),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(p,(essence?MirrorContent.ESSENTIA:MirrorContent.MIRROR).get().defaultBlockState().setValue(MirrorBlock.FACING,face));return (MirrorEntity)l.getBlockEntity(p);}
 static net.minecraftforge.items.IItemHandler handler(MirrorEntity m){return m.getCapability(net.minecraftforge.common.capabilities.ForgeCapabilities.ITEM_HANDLER,Direction.UP).orElseThrow(()->new AssertionError("mirror lacks input capability"));}
 static ItemEntity drop(ServerLevel l,BlockPos p,ItemStack stack){var e=new ItemEntity(l,p.getX()+.5,p.getY()+.05,p.getZ()+.5,stack);l.addFreshEntity(e);return e;}
 static void clean(ServerLevel l,BlockPos p){l.getEntitiesOfClass(ItemEntity.class,new AABB(p).inflate(3)).forEach(Entity::discard);}
 static AlchemyMachine jar(ServerLevel l,BlockPos p,String aspect,int amount){l.setBlockAndUpdate(p,AlchemyContent.JAR.get().defaultBlockState());var jar=(AlchemyMachine)l.getBlockEntity(p);if(amount>0)check(jar.insertEssence(aspect,amount,false),"jar setup");return jar;}
 static void recipes(ServerLevel l){var recipeInput=net.minecraft.world.item.crafting.CraftingInput.of(2,1,List.of(new ItemStack(thaumcraft.content.BasicContent.QUICKSILVER.get()),new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.withDefaultNamespace("green_stained_glass_pane")))));var glass=l.recipeAccess().getRecipes().stream().map(h->h.value()).filter(r->r instanceof thaumcraft.crafting.ArcaneRecipe).map(r->(thaumcraft.crafting.ArcaneRecipe)r).filter(r->r.matches(recipeInput,l)&&r.assemble(recipeInput).is(thaumcraft.content.SimpleContent.ITEMS.get("mirrored_glass").get())).findFirst().orElseThrow();check(glass.vis()==50&&glass.crystals().equals(Map.of("aqua",1,"ordo",1)),"original mirrored glass costs/tag");int count=0;for(var h:l.recipeAccess().getRecipes())if(h.value() instanceof thaumcraft.infusion.InfusionRecipe r&&Set.of("MIRROR","MIRRORESSENTIA","MIRRORHAND").contains(r.research())){check(r.components().size()==(r.research().equals("MIRRORHAND")?3:4),"mirror recipe offerings");check(r.instability()==(r.research().equals("MIRROR")?1:r.research().equals("MIRRORESSENTIA")?2:5),"mirror recipe instability");count++;}check(count==3,"missing original mirror infusions");Thaumcraft.LOGGER.info("MIRRORS_RECIPES_OK: native stained-pane mirrored glass matching and original costs plus all three registered mirror infusions");}
 static void nativeBinding(ServerLevel l){var anchor=create(l,P.west(6),false,Direction.UP);var p=PrimordialProbe.fake(l);p.getInventory().clearContent();p.setPos(Vec3.atBottomCenterOf(P.west(7)));p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(MirrorContent.MIRROR.get()));var first=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(anchor.getBlockPos()),Direction.UP,anchor.getBlockPos(),false));check(((MirrorItem)p.getMainHandItem().getItem()).onItemUseFirst(p.getMainHandItem(),first).consumesAction()&&p.getMainHandItem().get(MirrorContent.LINK.get()).equals(anchor.address()),"native mirror sampling failed");var at=P.west(8);l.setBlockAndUpdate(at.below(),Blocks.STONE.defaultBlockState());var cancel=new java.util.concurrent.atomic.AtomicBoolean(true);net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent.BUS.addListener(e->cancel.get()&&e.getPos().equals(at));var use=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()),Direction.UP,at.below(),false));check(!p.getMainHandItem().useOn(use).consumesAction()&&l.isEmptyBlock(at)&&anchor.link()==null&&!p.getMainHandItem().isEmpty(),"cancelled native placement mutated remote link or consumed mirror");cancel.set(false);use=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()),Direction.UP,at.below(),false));check(p.getMainHandItem().useOn(use).consumesAction()&&l.getBlockEntity(at) instanceof MirrorEntity&&anchor.link()==null,"native placement did not defer remote commit");var placed=(MirrorEntity)l.getBlockEntity(at);placed.serverTick();check(placed.peer()==anchor&&anchor.peer()==placed,"native pending mirror did not establish link next tick");Thaumcraft.LOGGER.info("MIRRORS_NATIVE_BINDING_OK: actual bound block item placement, Forge cancellation with no remote mutation/payment, and reciprocal commit on next server tick");}
 static void items(ServerLevel l){var a=create(l,P,false,Direction.UP);var b=create(l,P.east(8),false,Direction.UP);check(a.bind(b.address())&&a.peer()==b&&b.peer()==a,"reciprocal item link");check(!a.bind(a.address()),"self link accepted");var named=new ItemStack(Items.DIAMOND,64);named.set(DataComponents.CUSTOM_NAME,Component.literal("Mirror component proof"));named.set(thaumcraft.equipment.EquipmentContent.RUNIC.get(),2);var input=handler(a);check(input.insertItem(0,named,true).isEmpty()&&b.queued()==0&&a.instability()==0,"simulation modified queue or instability");check(input.insertItem(0,named,false).isEmpty()&&named.getCount()==64&&b.queued()==64&&a.instability()==64,"capability payment/queue");check(input.extractItem(0,64,false).isEmpty()&&input.getStackInSlot(0).isEmpty(),"phantom extractable inventory");var physical=drop(l,P,new ItemStack(Items.EMERALD,5));check(a.transport(physical)&&physical.isRemoved()&&b.queued()==69&&!a.transport(physical),"physical transfer/replay");
 net.minecraftforge.event.entity.EntityJoinLevelEvent.BUS.addListener(e->denySpawn&&e.getEntity() instanceof ItemEntity);denySpawn=true;check(!b.ejectOne()&&b.queued()==69,"cancelled spawn consumed queued item");denySpawn=false;check(b.ejectOne()&&b.queued()==68&&b.instability()==1,"single-item ejection");var emitted=l.getEntitiesOfClass(ItemEntity.class,new AABB(P.east(8)).inflate(2)).stream().filter(e->e.getItem().is(Items.DIAMOND)).findFirst().orElseThrow();check(emitted.getItem().getCount()==1&&emitted.getItem().getHoverName().getString().equals("Mirror component proof")&&emitted.getItem().getOrDefault(thaumcraft.equipment.EquipmentContent.RUNIC.get(),0)==2,"ejection lost components");emitted.setPos(P.getX()+8.5,P.getY()+.05,P.getZ()+.5);check(!b.transport(emitted),"output was immediately reabsorbed");while(b.queued()>0)check(b.ejectOne(),"queue could not empty");clean(l,P.east(8));
 check(b.accept(new ItemStack(Items.COBBLESTONE,1727),false).isEmpty()&&b.queued()==1727,"bounded queue capacity");var overflow=drop(l,P,new ItemStack(Items.COBBLESTONE,4));check(a.transport(overflow)&&overflow.isAlive()&&overflow.getItem().getCount()==3&&b.queued()==1728,"partial destination did not retain exact remainder");check(!a.transport(overflow)&&overflow.getItem().getCount()==3,"full destination swallowed source");overflow.discard();var relocated=b.droppedItem();l.destroyBlock(P.east(8),false);check(l.getEntitiesOfClass(ItemEntity.class,new AABB(P.east(8)).inflate(3)).stream().filter(e->e.getItem().is(Items.COBBLESTONE)).mapToInt(e->e.getItem().getCount()).sum()==1728,"break lost/duplicated queued goods");clean(l,P.east(8));var restored=create(l,P.east(9),false,Direction.UP);check(relocated.get(DataComponents.BLOCK_ENTITY_DATA).loadInto(restored,l.registryAccess()),"native block item data rejected");check(restored.queued()==0&&restored.bind(a.address())&&a.peer()==restored,"relocation/reciprocal repair");var old=a.link();l.destroyBlock(P.east(9),false);create(l,P.east(9),false,Direction.UP);a.remember(old);check(a.peer()==null&&input.insertItem(0,new ItemStack(Items.DIAMOND),false).getCount()==1,"replacement hijacked stale identity");
 var far=new MirrorAddress(GlobalPos.of(Level.OVERWORLD,new BlockPos(25000000,100,25000000)),UUID.randomUUID().toString());check(!l.hasChunkAt(far.location().pos()),"unloaded test position already loaded");a.remember(far);check(a.peer()==null&&!a.bind(far)&&!l.hasChunkAt(far.location().pos()),"mirror loaded a missing destination chunk");var future=a.droppedItem().get(DataComponents.BLOCK_ENTITY_DATA).copyTagWithoutId();future.getCompoundOrEmpty("mirror").putInt("version",2);check(net.minecraft.world.item.component.TypedEntityData.of(MirrorContent.TYPE.get(),future).loadInto(a,l.registryAccess())&&!a.supported(),"future data not disabled");check(a.accept(new ItemStack(Items.DIAMOND),false).getCount()==1&&a.droppedItem().get(DataComponents.BLOCK_ENTITY_DATA).copyTagWithoutId().getCompoundOrEmpty("mirror").getIntOr("version",0)==2,"future data altered or inventory enabled");Thaumcraft.LOGGER.info("MIRRORS_ITEMS_OK: reciprocal identities, simulation, physical/capability transfer, component retention, spawn-cancel conservation, output immunity, bounded/full queue, exact break drops, relocation, stale replacement and no forced chunk load");}
 static void crossAndHand(ServerLevel l,ServerLevel nether){var source=create(l,P.south(5),false,Direction.UP);var target=create(nether,N,false,Direction.UP);check(source.bind(target.address())&&target.peer()==source,"cross-dimensional pair failed");check(handler(source).insertItem(0,new ItemStack(Items.GOLD_INGOT,6),false).isEmpty()&&target.queued()==6,"cross-dimensional item transfer");actor=PrimordialProbe.fake(l);actor.getInventory().clearContent();actor.getInventory().setSelectedSlot(0);var hand=new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("hand_mirror").get());hand.set(MirrorContent.LINK.get(),target.address());actor.setItemInHand(InteractionHand.MAIN_HAND,hand);actor.getInventory().setItem(9,new ItemStack(Items.EMERALD,3));var menu=new HandMirrorMenu(1,actor.getInventory(),hand,0);check(!menu.quickMoveStack(actor,1).isEmpty()&&actor.getInventory().getItem(9).isEmpty(),"hand mirror shift move");menu.broadcastChanges();check(menu.getSlot(0).getItem().isEmpty()&&target.queued()==9,"hand delivery duplicated or lost items");check(menu.quickMoveStack(actor,28).isEmpty()&&actor.getMainHandItem()==hand,"held hand mirror not locked");var missing=new MirrorAddress(GlobalPos.of(Level.OVERWORLD,new BlockPos(25000000,100,25000000)),UUID.randomUUID().toString());hand.set(MirrorContent.LINK.get(),missing);check(!menu.stillValid(actor),"rebound mirror kept old menu valid");var pending=new HandMirrorMenu(2,actor.getInventory(),hand,0);pending.getSlot(0).setByPlayer(new ItemStack(Items.DIAMOND,2));pending.broadcastChanges();check(pending.getSlot(0).getItem().getCount()==2,"unloaded hand destination swallowed items");check(!pending.quickMoveStack(actor,0).isEmpty(),"failed hand delivery could not be retrieved");
 l.setBlockAndUpdate(P.east(13),Blocks.CHEST.defaultBlockState());((ChestBlockEntity)l.getBlockEntity(P.east(13))).setItem(0,hand.copy());Thaumcraft.LOGGER.info("MIRRORS_CROSS_HAND_OK: real cross-dimensional queue, hand-menu shift transfer, held-slot lock, stale-menu rejection, failed delivery retained/retrieved and bound item saved");}
 static void essence(ServerLevel l){var a=create(l,P.north(5),true,Direction.SOUTH);var b=create(l,P.east(8).north(5),true,Direction.SOUTH);check(a.bind(b.address()),"essence pair failed");check(!a.bind(((MirrorEntity)l.getBlockEntity(P.south(5))).address()),"mixed mirror types linked");var supply=jar(l,b.getBlockPos().south(2),"aer",7);var behind=jar(l,b.getBlockPos().north(2),"aqua",20);jar(l,b.getBlockPos().south(8),"aqua",20);check(a.contents(Direction.UP).getOrDefault("aer",0)==7&&!a.contents(Direction.UP).containsKey("aqua"),"original forward half volume violated");check(a.extract("aer",Direction.UP,true)&&supply.total()==7&&a.instability()==0,"essence simulation consumed source");check(a.extract("aer",Direction.UP,false)&&supply.total()==6&&a.instability()==1,"essence extraction/payment");check(MirrorEssence.drain(l,a.getBlockPos(),"aer")&&supply.total()==5,"infusion source integration");check(a.insert("aer",Direction.UP,false)&&supply.total()==6&&!a.insert("aqua",Direction.UP,false),"filtered insertion or range");var receiver=jar(l,a.getBlockPos().below(),"",0);check(thaumcraft.essentia.EssentiaNetwork.pull(l,receiver.getBlockPos(),receiver,Direction.UP)&&receiver.total()==1&&supply.total()==5,"native tube/jar network did not pull remote essence");check(behind.total()==20,"out-of-volume jar touched");check(supply.extractEssence("aer",5,false),"alias regression setup");int before=a.instability();check(!thaumcraft.essentia.EssentiaNetwork.pull(l,receiver.getBlockPos(),receiver,Direction.UP)&&receiver.total()==1&&a.instability()==before,"remote source drained its own receiving jar");check(supply.insertEssence("aer",5,false),"restore alias fixture");var empty=jar(l,b.getBlockPos().south(),"",0);check(a.insert("aer",Direction.UP,false)&&empty.total()==0&&supply.total()==6,"insertion did not prefer existing nonempty jar");check(supply.extractEssence("aer",1,false),"restore priority fixture");l.destroyBlock(empty.getBlockPos(),false);float flux=thaumcraft.aura.AuraManager.get(l,a.getBlockPos()).flux();a.addInstability(65-a.instability());a.serverTick();check(a.instability()==1&&thaumcraft.aura.AuraManager.get(l,a.getBlockPos()).flux()==flux+1,"essence instability did not pollute at original threshold");Thaumcraft.LOGGER.info("MIRRORS_ESSENCE_OK: forward-eight remote jars, extraction/insertion/simulation conservation, excluded back/range/mirror recursion, native network and infusion-source integration, original instability flux");}

 static thaumcraft.infusion.InfusionPedestal pedestal(ServerLevel l,BlockPos p,ItemStack stack){l.setBlockAndUpdate(p,thaumcraft.infusion.InfusionContent.ARCANE.get().defaultBlockState());var result=(thaumcraft.infusion.InfusionPedestal)l.getBlockEntity(p);check(result.setItem(stack),"matrix pedestal refused item");return result;}
 static void matrix(ServerLevel l,ServerLevel nether){var p=P.offset(-5,3,9);for(var q:BlockPos.betweenClosed(p.offset(-4,-3,-4),p.offset(4,2,4)))l.setBlockAndUpdate(q,q.getY()==p.getY()-3?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p,thaumcraft.infusion.InfusionContent.MATRIX.get().defaultBlockState());var center=pedestal(l,p.below(2),new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("mirrored_glass").get()));for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})l.setBlockAndUpdate(p.offset(x,-2,z),thaumcraft.content.SimpleContent.BLOCKS.get("pillar_arcane").get().defaultBlockState());pedestal(l,p.offset(-3,-2,0),new ItemStack(Items.GOLD_INGOT));pedestal(l,p.offset(3,-2,0),new ItemStack(Items.GOLD_INGOT));pedestal(l,p.offset(0,-2,-3),new ItemStack(Items.GOLD_INGOT));pedestal(l,p.offset(0,-2,3),new ItemStack(Items.ENDER_PEARL));var source=create(l,p.east(4).below(2),true,Direction.UP);var target=create(nether,N.east(6),true,Direction.UP);check(source.bind(target.address()),"matrix remote pair");var first=jar(nether,N.east(8).above(),"motus",25);var second=jar(nether,N.east(4).above(),"tenebrae",25);var third=jar(nether,N.east(6).south(2).above(),"permutatio",25);var known=thaumcraft.research.KnowledgeState.EMPTY.stage("INFUSION",99).stage("MIRROR",99);check(thaumcraft.research.KnowledgeStore.write(actor,known),"matrix fixture research");var m=(thaumcraft.infusion.InfusionMatrix)l.getBlockEntity(p);check(m.assemble(actor,new ItemStack(thaumcraft.crafting.ArcaneContent.SALIS.get())),"native mirror altar assembly");for(int i=0;i<1500&&m.stability()<25;i++)m.serverTick();check(m.start(actor),"native mirror infusion failed to start");for(int i=0;i<800&&m.job()!=null;i++)m.serverTick();check(m.job()==null&&center.item().is(MirrorContent.MIRROR.get().asItem())&&first.total()+second.total()+third.total()==0&&source.instability()==75,"native infusion did not pay remote 75 essence exactly");Thaumcraft.LOGGER.info("MIRRORS_INFUSION_OK: full original mirror infusion completed using only three jars in the Nether, all 75 essentia paid and all four physical offerings consumed");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("mirrors-"))return;var l=e.server().overworld();var nether=e.server().getLevel(Level.NETHER);if(++ticks<80||stage==9)return;if(stage==0){for(int x=216;x<=219;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);if(nether!=null&&!mode().equals("mirrors-client"))nether.setChunkForced(N.getX()>>4,N.getZ()>>4,true);due=l.getGameTime()+80;stage=1;return;}if(l.getGameTime()<due)return;stage=9;recipes(l);
 if(mode().equals("mirrors-read")){var source=(MirrorEntity)l.getBlockEntity(P.south(5));var target=(MirrorEntity)nether.getBlockEntity(N);int received=target.queued()+nether.getEntitiesOfClass(ItemEntity.class,new AABB(N).inflate(4)).stream().filter(it->it.getItem().is(Items.GOLD_INGOT)||it.getItem().is(Items.EMERALD)).mapToInt(it->it.getItem().getCount()).sum();check(source.peer()==target&&target.peer()==source&&received==9,"restart lost cross-dimensional pair/queue or replayed output");var chest=(ChestBlockEntity)l.getBlockEntity(P.east(13));check(chest.getItem(0).has(MirrorContent.LINK.get()),"restart lost hand mirror component");var a=(MirrorEntity)l.getBlockEntity(P.north(5));var remote=(AlchemyMachine)l.getBlockEntity(P.east(8).north(5).south(2));var receiver=(AlchemyMachine)l.getBlockEntity(P.north(5).below());check(a.peer()!=null&&remote.total()+receiver.total()==6,"restart lost essence link/source or native flow conservation");Thaumcraft.LOGGER.info("MIRRORS_RESTART_OK: native cross-dimensional identities, queued item components, hand binding and remote essentia survived restart");e.server().halt(false);return;}
 l.getEntitiesOfClass(Entity.class,new AABB(P).inflate(28),en->!(en instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);for(var q:BlockPos.betweenClosed(P.offset(-10,-2,-10),P.offset(15,6,13)))l.setBlockAndUpdate(q,q.getY()==P.getY()-2?Blocks.GLOWSTONE.defaultBlockState():Blocks.AIR.defaultBlockState());
 if(nether!=null&&!mode().equals("mirrors-client")){for(var q:BlockPos.betweenClosed(N.offset(-8,-2,-8),N.offset(10,4,8)))nether.setBlockAndUpdate(q,q.getY()==N.getY()-2?Blocks.GLOWSTONE.defaultBlockState():Blocks.AIR.defaultBlockState());nether.getEntitiesOfClass(ItemEntity.class,new AABB(N).inflate(30)).forEach(Entity::discard);}l.getEntitiesOfClass(ItemEntity.class,new AABB(P).inflate(28)).forEach(Entity::discard);
 if(mode().equals("mirrors-client")){if(e.server().getPlayerList().getPlayers().isEmpty()){stage=1;return;}actor=e.server().getPlayerList().getPlayers().getFirst();actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.getInventory().clearContent();actor.teleportTo(l,P.getX()+.5,P.getY()+2,P.getZ()+7.5,Set.of(),180,25,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();var a=create(l,P.west(2),false,Direction.UP);var b=create(l,P.east(2),false,Direction.UP);check(a.bind(b.address()),"client item pair");var hand=new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("hand_mirror").get());hand.set(MirrorContent.LINK.get(),b.address());actor.getInventory().setItem(0,hand);var unavailable=hand.copy();unavailable.set(MirrorContent.LINK.get(),new MirrorAddress(GlobalPos.of(Level.OVERWORLD,new BlockPos(25000000,100,25000000)),UUID.randomUUID().toString()));actor.getInventory().setItem(1,unavailable);actor.getInventory().setItem(10,new ItemStack(Items.IRON_INGOT,3));actor.getInventory().setItem(9,new ItemStack(Items.DIAMOND,8));actor.getInventory().setSelectedSlot(0);create(l,P.north(3),true,Direction.SOUTH);ready=true;Thaumcraft.LOGGER.info("MIRRORS_CLIENT_READY: original mirror frame scene, hand destination and eight physical inventory diamonds; open hand mirror and shift-click diamonds");return;}
 nativeBinding(l);items(l);crossAndHand(l,nether);essence(l);matrix(l,nether);e.server().halt(false);}
